BEGIN;
ALTER TABLE operacion DISABLE TRIGGER trg_operacion_periodo_cerrado;
ALTER TABLE operacion_detalle DISABLE TRIGGER trg_detalle_periodo_cerrado;

-- 1. INSERTAR PERIODOS DE 2023 (6 MESES: JUL 2023 A DIC 2023)

-- 2. INSERTAR OPERACIONES Y DETALLES DE 2023 (RECIBOS 1 AL 83)

-- 3. RECLASIFICAR REINVERSIONES DE UTILIDAD EN ACCIONES DE JUNIO 2025 (FUSIONAR CONCEPTO 5 EN CONCEPTO 4)
UPDATE operacion_detalle od4
SET monto = od4.monto + od5.monto
FROM operacion_detalle od5
JOIN operacion o ON o.id = od5.operacion_id
JOIN periodo p ON p.id = o.periodo_id
WHERE od4.operacion_id = od5.operacion_id
  AND od4.concepto_id = 4
  AND od5.concepto_id = 5
  AND p.anio = 2025
  AND p.mes = 6
  AND od5.monto IN (180.00, 750.00, 240.00, 690.00, 1380.00, 1140.00, 840.00, 150.00);
DELETE FROM operacion_detalle od5
USING operacion o, periodo p
WHERE od5.operacion_id = o.id
  AND o.periodo_id = p.id
  AND p.anio = 2025
  AND p.mes = 6
  AND od5.concepto_id = 5
  AND od5.monto IN (180.00, 750.00, 240.00, 690.00, 1380.00, 1140.00, 840.00, 150.00);

ALTER TABLE operacion ENABLE TRIGGER trg_operacion_periodo_cerrado;
ALTER TABLE operacion_detalle ENABLE TRIGGER trg_detalle_periodo_cerrado;
COMMIT;